-- University of South Australia (UniSA) course updates

-- Course: Bachelor of Laws (Honours) (115725G)
UPDATE courses SET
    course_description = '<p>The Bachelor of Laws (Honours) is your path to become a lawyer or legal professional.</p><p>You’ll build a foundation in how the law works – and how and why laws change over time. Research past decisions to understand precedent and learn to analyse and interpret laws, regulations and court rulings. </p><p>Debate the future of law and explore emerging areas like artificial intelligence (AI) and sustainability. Embrace your social conscience as a champion for environmental sustainability and climate action. Be inspired by engaging, award-winning teachers and leading researchers in areas such as international law as you prepare for an international career. </p><p>Learn about the importance of ethics and professional conduct and how to uphold the integrity of the legal system with fairness and equality. Graduate ready to guide strategy and decision-making for small business to large corporations.</p><p>Please note: further study is required to be admitted to legal practice. You will need to fulfil the practical requirements for admission, which include completion of the Graduate Diploma in Legal Practice. </p>',
    course_duration_per_week = 208,
    total_course_duration = '4 year(s) full-time',
    offshore_tuition_fee = 54900,
    onshore_tuition_fee = NULL,
    entry_requirements = '<table><tbody><tr><td><strong>Academic Requirements</strong></td><td><ul><li>Completion of secondary education equivalent to South Australian Certificate of Education (SACE)</li><li>Successful completion of at least 6 months full-time study (or equivalent part-time) in an undergraduate diploma (AQF level 5) or higher</li></ul></td></tr><tr><td><strong>English Proficiency</strong></td><td><ul><li>IELTS Overall 7, Reading 7, Listening 7, Speaking 7, Writing 7</li><li>International students with English as an additional language must provide certified documentation from educational institution/employer confirming English as language of instruction/employment</li></ul></td></tr><tr><td><strong>Other</strong></td><td><ul><li>Admission is competitive with ranks based on entry criteria</li><li>Possession of listed qualifications does not guarantee admission</li><li>Country-specific requirements (e.g., Australia ATAR 85, Bangladesh HSC 4.95, etc.)</li></ul></td></tr></tbody></table>',
    apply_form = 'https://adelaideuni.edu.au/study/degrees/bachelor-of-laws-honours/',
    updated_at = NOW()
WHERE cricos_course_code = '115725G';

-- Course: Bachelor of Laws (Honours), Bachelor of Arts (117408D)
UPDATE courses SET
    course_description = '<p>A double degree in Bachelor of Laws (Honours), Bachelor of Arts from Adelaide University will deepen your legal knowledge by providing broader context and perspective. You’ll be skilled to leverage legal expertise with a deep understanding of social, cultural and human behaviour. You’ll build a foundation in how the law works – and how and why laws change over time. </p><p>If you’re passionate about fairness, social justice and making a meaningful contribution, studying law and arts will equip you to make a tangible difference. Your advanced problem-solving skills will enable you to guide others through legal challenges, advocating for their interests with integrity and commitment. </p><p>You’ll graduate with an advanced understanding of legal principles of Australian law and humanities. This legal expertise, combined with the knowledge and skills you’ll gain from your Bachelor of Arts double degree, will set you on track for an impactful career. </p>',
    course_duration_per_week = 260,
    total_course_duration = '5 year(s) full-time',
    offshore_tuition_fee = 54900,
    onshore_tuition_fee = NULL,
    entry_requirements = '<table><tbody><tr><td><strong>Academic Requirements</strong></td><td><ul><li>Completion of secondary education equivalent to South Australian Certificate of Education (SACE)</li><li>Successful completion of at least 6 months full-time study (or equivalent part-time) in an undergraduate diploma (AQF level 5) or higher</li></ul></td></tr><tr><td><strong>English Proficiency</strong></td><td><ul><li>IELTS Overall 7, Reading 7, Listening 7, Speaking 7, Writing 7</li><li>International students with English as an additional language must provide certified documentation from educational institution/employer confirming English as language of instruction/employment</li></ul></td></tr><tr><td><strong>Other</strong></td><td><ul><li>Admission is competitive with ranks based on entry criteria</li><li>Possession of listed qualifications does not guarantee admission</li><li>Country-specific requirements (e.g., Australia ATAR 85, Bangladesh HSC 4.95, etc.)</li></ul></td></tr></tbody></table>',
    apply_form = 'https://adelaideuni.edu.au/study/degrees/bachelor-of-laws-honours-bachelor-of-arts/',
    updated_at = NOW()
WHERE cricos_course_code = '117408D';

-- Course: Bachelor of Software Engineering (Honours) (115758J)
UPDATE courses SET
    course_description = '<p>Our Bachelor of Software Engineering (Honours) will equip you with the specialist knowledge, technical skills and software development practices to professionally practice as a software engineer.</p><p>Be exposed to a blend of theoretical knowledge and applied practical skills to develop a deep understanding of how software solutions are designed and built.</p><p>You’ll develop the knowledge, principles and systematic practices of software requirements, design, development and testing to produce reliable, maintainable and scalable software solutions.</p><p>Apply your knowledge and skills during your final year in a real-world project, collaborating with industry professionals to gain practical experience.</p><p>Graduate armed with industry tools and processes to solve complex problems and inspire innovation in companies. You’ll be highly skilled and equipped to work in IT companies and organisations that develop small to large software solutions, or large, complex software solutions and systems.</p>',
    course_duration_per_week = 208,
    total_course_duration = '4 year(s) full-time',
    offshore_tuition_fee = 54900,
    onshore_tuition_fee = NULL,
