-- Course: Master of Financial Planning (115916M)
UPDATE courses SET
    course_description = '<p>Our Master of Financial Planning will give you the educational requirements needed to progress into a career as a financial planner. By completing this program, you’ll widen your career prospects and join an in-demand industry. </p><p>Learn the basics of business, covering quantitative methods, economic principles, accounting concepts and methods, and principles of finance. Then, you’ll get into more advanced topics such as commercial and business law, advanced investment management, risk management and insurance, estate planning, taxation law and applied financial planning. Tailor your studies with elective courses so you can go deeper into topics that interest you. </p><p>Emerge a confident professional, ready to take the next step towards becoming a financial planner. You might find work in financial institutions, investment banks, superannuation and insurance funds or financial advisory firms. </p>',
    course_duration_per_week = 104,
    total_course_duration = '2 year(s) full-time',
    offshore_tuition_fee = 52200,
    onshore_tuition_fee = NULL,
    entry_requirements = '<table><tbody><tr><td><strong>Academic Requirements</strong></td><td><ul><li>A completed bachelor (AQF level 7) or bachelor honours (AQF level 8) degree or equivalent from a recognised higher education institution; OR</li><li>A completed nested or related graduate certificate (AQF level 8) or higher or equivalent from a recognised higher education institution.</li><li>In cases where there are more eligible applicants than available places, admission will be competitive with ranks based on the entry criteria.</li><li>Possession of English qualifications, in addition to the academic entry requirements, does not guarantee a place; applications are considered individually and selection is competitive.</li></ul></td></tr><tr><td><strong>English Proficiency</strong></td><td><ul><li>International students who speak English as an additional language must have obtained one of the following standards within the last two years prior to admission.</li><li>Where previous study/work experience was conducted in English, the application must be accompanied by certified documentation from the educational institution/employer certifying that the language of instruction/employment was English.</li><li>IELTS Overall 6.5</li><li>IELTS Reading 6</li><li>IELTS Listening 6</li><li>IELTS Speaking 6</li><li>IELTS Writing 6</li><li>Equivalent English qualifications link provided for comprehensive list of accepted tests and other information.</li></ul></td></tr></tbody></table>',
    apply_form = 'https://adelaideuni.edu.au/study/degrees/master-of-financial-planning/',
    updated_at = NOW()
WHERE cricos_course_code = '115916M';

-- Course: Bachelor of Science (Honours) (115753C)
UPDATE courses SET
    course_description = '<p>If you’re fascinated by the universe and keen to explore the science behind it, the Bachelor of Science (Honours) majoring in Space Science and Astrophysics is your launchpad. </p><p>This degree offers a strong foundation in physics, astronomy and computational methods, with opportunities to work on real-world experiments and data from ground and space observatories. </p><p>You’ll investigate everything from the structure of stars to the future of space exploration, developing practical skills in data analysis, programming and scientific research. </p><p>Through small group projects and expert-led teaching, you’ll build critical thinking, teamwork and analytical abilities. With the global space sector rapidly expanding, you’ll graduate equipped to meet the growing demand for scientists in government, industry, and research settings. </p>',
    course_duration_per_week = 208,
    total_course_duration = '4 year(s) full-time',
    offshore_tuition_fee = 53300,
    onshore_tuition_fee = NULL,
    entry_requirements = '<table><tbody><tr><td><strong>Academic Requirements</strong></td><td><ul><li>Completion of a secondary education qualification equivalent to the South Australian Certificate of Education (SACE)</li><li>Completion of an award from a registered training organisation (RTO) at Certificate IV (AQF level 4) or higher</li><li>Successful completion of at least 6 months full-time study (or equivalent part-time) in a higher education award program in an undergraduate diploma (AQF level 5) or higher</li><li>This degree requires a Grade Point Average (GPA) equivalent to an Adelaide University 5.0 on a 7-point scale for entry</li><li>Admission will be competitive with ranks based on the entry criteria where there are more eligible applicants than available places</li></ul></td></tr><tr><td><strong>English Proficiency</strong></td><td><ul><li>International students who speak English as an additional language must have obtained one of the following standards within the last two years prior to admission</li><li>Where previous study/work experience was conducted in English, the application must be accompanied by certified documentation from the educational institution/employer certifying that the language of instruction/employment was English</li><li>IELTS Overall 6.5</li><li>IELTS Reading 6</li><li>IELTS Listening 6</li><li>IELTS Speaking 6</li><li>IELTS Writing 6</li><li>Equivalent English qualifications link provided by Adelaide University</li><li>Possession of qualifications in addition to academic entry requirements does not guarantee a place; applications considered individually and selection is competitive</li></ul></td></tr><tr><td><strong>International admissions by country</strong></td><td><ul><li>Australia ATAR 85</li><li>Bangladesh Higher Secondary Certificate (HSC) 4.95</li><li>Canada Ontario Secondary School Diploma (OSSD) 80%</li><li>China Gaokao 75%</li><li>Denmark Studentereksamen (stx: Upper Secondary School Diploma) 7 (Good)</li><li>Franc