-- Course: Master of Business Administration (115899G)
UPDATE courses SET
    course_description = '<p>If you’re a professional wanting to deepen your understanding on how successful companies operate, Adelaide University’s Master of Business Administration specialising in Finance is for you.</p><p>In 1.5 years, you’ll learn to navigate modern business challenges and give global teams the tools to deliver exceptional results. You’ll also develop specialised knowledge in finance to spearhead business growth.</p><p>Graduate with an in-demand skillset and a network of executive leaders and professionals.</p>',
    course_duration_per_week = 78,
    total_course_duration = '1.5 year(s) full-time',
    offshore_tuition_fee = 54900,
    onshore_tuition_fee = NULL,
    entry_requirements = '<table><tbody><tr><td><strong>Academic Requirements</strong></td><td><ul><li>A completed bachelor (AQF level 7) or bachelor honours (AQF level 8) degree or equivalent from a recognised higher education institution</li><li>A minimum of 3 years of full-time (or equivalent) professional experience</li></ul></td></tr><tr><td><strong>English Proficiency</strong></td><td><ul><li>International students who speak English as an additional language must have obtained one of the following standards within the last two years prior to admission</li><li>Where previous study/work experience was conducted in English, the application must be accompanied by certified documentation from the educational institution/employer certifying that the language of instruction/employment was English</li><li>IELTS Overall 7</li><li>IELTS Reading 6</li><li>IELTS Listening 6</li><li>IELTS Speaking 6</li><li>IELTS Writing 6</li><li>Access link for comprehensive list of English language tests accepted and other important information: Equivalent English qualifications</li></ul></td></tr></tbody></table>',
    apply_form = 'https://adelaideuni.edu.au/study/degrees/master-of-business-administration-finance/',
    updated_at = NOW()
WHERE cricos_course_code = '115899G';

-- Course: Bachelor of Sustainability and Climate Change (115760D)
UPDATE courses SET
    course_description = '<p>Adelaide University will equip you with the knowledge and skills to address pressing challenges emerging from global climate change.</p><p>Your Anthropology major will explore patterns, connections and commonalities across culture and society. Build an understanding of what it means to be human in our diversified world. Uncover patterns, connections and commonalities across different societies. Gain qualitative research skills to better understand what it means to be a human.</p><p>This degree combines the analytical and research skills of anthropology with specialised knowledge in sustainability and climate change. Graduates will be valuable in various fields addressing environmental and social challenges. You’ll contribute to organisations like government, non-profits and research institutions. Help build a resilient and equitable future for our planet. Become a leader capable of driving meaningful change.</p>',
    course_duration_per_week = 156,
    total_course_duration = '3 year(s) full-time',
    offshore_tuition_fee = 54900,
    onshore_tuition_fee = NULL,
