-- Course: Master of Professional Engineering (Mechatronic) (115948C)
UPDATE courses SET
    course_description = '<p>Our Master of Professional Engineering (Mechatronic) is designed to challenge and extend, assisting you to take your mechatronic engineering career to the next level.</p><p>You’ll study higher-level courses in advanced electromechanical systems, control technology, machine learning, robotics and autonomous systems.</p><p>Core courses in engineering management and data analytics enable you to deepen and formalise your project management expertise.</p><p>Our wide range of electives give you the freedom to tailor your studies to your specific interests and career goals. Whether that’s advanced signal processing, biomedical instrumentation, autonomous robotic systems – or something else entirely – you’ll find plenty of options.</p><p>Your learning won’t only be theory. Deeply practical, you’ll put your knowledge into practice through capstone design-and-build projects, a major research project and up to 450 hours of industry placement.</p><p>These experiences come together to ensure you’ll graduate with the advanced technical and professional skills needed to achieve your career goals.</p>',
    course_duration_per_week = 104,
    total_course_duration = '2 year(s) full-time',
    offshore_tuition_fee = 54900,
    onshore_tuition_fee = NULL,
    entry_requirements = '<table><tbody><tr><td><strong>Academic Requirements</strong></td><td>A completed 4-year bachelor or bachelor honours degree or higher in a field relevant to the chosen engineering specialisation from a recognised higher education institution</td></tr><tr><td><strong>English Proficiency</strong></td><td><ul><li>International students who speak English as an additional language must have obtained one of the following standards within the last two years prior to admission</li><li>IELTS Overall 6.5</li><li>IELTS Reading 6</li><li>IELTS Listening 6</li><li>IELTS Speaking 6</li><li>IELTS Writing 6</li><li>Where previous study/work experience was conducted in English, the application must be accompanied by certified documentation from the educational institution/employer certifying that the language of instruction/employment was English</li></ul></td></tr></tbody></table>',
    apply_form = 'https://adelaideuni.edu.au/study/degrees/master-of-professional-engineering-mechatronic/',
    updated_at = NOW()
WHERE cricos_course_code = '115948C';

-- Course: Master of Engineering (Maritime) (115911E)
UPDATE courses SET
    course_description = '<p>Our Master of Engineering (Maritime) is designed to challenge and extend, elevating you to take your engineering career to the next level. </p><p>You’ll study higher-level courses in advanced systems engineering, submarine design, naval architecture and shipbuilding programs – building a formidable knowledgebase. Deepen and formalise your project management expertise in engineering management and data analytics courses. </p><p>Our wide range of electives give you the freedom to tailor your studies to your specific interests and career goals. Whether that’s defence leadership, autonomous robotic systems or advanced mechanics and materials - you’ll explore a range of disciplines. </p><p>Put your learning into practice through our hands-on curriculum. Complete a capstone design project, major research project and up to 450 hours of professional industry placement. </p><p>These experiences combine to ensure you graduate with the advanced technical and professional skills necessary to achieve your career goals. </p>',
    course_duration_per_week = 104,
    total_course_duration = '2 year(s) full-time',
    offshore_tuition_fee = 54900,
    onshore_tuition_fee = NULL,
    entry_requirements = '<table><tbody><tr><td><strong>Academic Requirements</strong></td><td>A completed four year bachelor (AQF7) or bachelor honours (AQF8) degree or equivalent in science, engineering, technology or a related field from a recognised higher education institution.</td></tr><tr><td><strong>English Proficiency</strong></td><td><ul><li>International students who speak English as an additional language must have obtained one of the following standards within the last two years prior to admission:</li><li>IELTS Overall 6.5</li><li>IELTS Reading 6</li><li>IELTS Listening 6</li><li>IELTS Speaking 6</li><li>IELTS Writing 6</li><li>Where previous study/work experience was conducted in English, the application must be accompanied by certified documentation from the educational institution/employer certifying that the language of instruction/employment was English</li></ul></td></tr></tbody></table>',
