-- Course: Master of Professional Accounting (115941K)
UPDATE courses SET
    course_description = '<p>Develop your analytical, business management and problem-solving skills with Adelaide University’s Master of Professional Accounting. You will build a diverse knowledgebase in accounting management, finance, commercial law, taxation law and auditing. You’ll also learn fundamental concepts, issues and benefits of information systems and technologies – preparing you for today’s business environment.</p><p>Choose from interesting electives to suit your career aspirations and preferences. Broaden your industry networks, studying alongside a diverse cohort of aspiring professionals and learning from industry-experienced teaching staff. Discover a world of opportunities in accounting, tax, financial management and public practice.</p>',
    course_duration_per_week = 78,
    total_course_duration = '1.5 year(s) full-time',
    offshore_tuition_fee = 52200,
    onshore_tuition_fee = NULL,
