-- Course: Bachelor of Medical Radiation Science (Honours) (115731J)
UPDATE courses SET
    course_description = '<p>The Bachelor of Medical Radiation (Honours) majoring in Nuclear Medicine at Adelaide University offers a comprehensive education in the dynamic field of nuclear medicine.</p><p>Explore areas like radiopharmaceuticals, diagnostic imaging, and patient care. Gain in-depth knowledge of how to diagnose and treat diseases. Use advanced technology. Learn from experts who are leaders in their field.</p><p>This degree will equip you with essential skills, including operating state-of-the-art imaging equipment and safely handling radioactive substances. Apply these skills through over 1,400 hours of hands-on clinical placements, starting from your second year.</p><p>Graduate well-prepared for diverse career opportunities in healthcare. You could work in a hospital, specialised clinic, or research facility. Make a significant impact on patient outcomes and contribute to the advancement of medical science.</p>',
    course_duration_per_week = 208,
    total_course_duration = '4 year(s) full-time',
    offshore_tuition_fee = 52200,
    onshore_tuition_fee = NULL,
