-- Course: Graduate Diploma in Marketing (115868C)
UPDATE courses SET
    course_description = '<p>Our Graduate Diploma in Marketing is a one-year degree designed to advance and refine your marketing skills. Be equipped to make strategic decisions to prepare you for future marketing leadership roles. </p><p>You’ll develop effective marketing strategies for diverse audiences. Identify trends, analyse consumer behaviour, examine analytical data, and communicate confidently. Study leadership and entrepreneurship and build a specialised skillset to equip you to lead on a global scale. </p><p>Gain first-hand, practical experience with a market research project and learn the marketing principles that are valuable across many business sectors – transferable to many roles and industries. Drive growth with your advanced communication and analytical skills and unlock senior marketing positions or start an exciting new career. </p>',
    course_duration_per_week = 52,
    total_course_duration = '1 year(s) full-time',
    offshore_tuition_fee = 50500,
    onshore_tuition_fee = NULL,
