-- Course: Bachelor of Laboratory Medicine (Honours) (115724H)
UPDATE courses SET
    course_description = '<p>Gain the skills and knowledge needed to work as a medical laboratory scientist in diagnostic pathology or research.</p><p>Develop core knowledge of the natural and biomedical sciences, and their application in diagnostic pathology. Learn how to perform diagnostic tests, including cross-matching for blood transfusions, identifying infection-causing organisms, screening for cancer cells and detecting genes responsible for disease conditions. Undertake training in all areas of pathology, including biochemistry, microbiology, immunology, molecular pathology, haematology and histopathology.</p><p>Put your learning into practice in a variety of private, public, community and allied health settings with up to 26 weeks of clinical placements. Get hands on in our purpose-built histopathology and haematology laboratories, where you’ll use industry-standard technology to perform, analyse and interpret test results. Gain advanced research skills and contribute new knowledge to the field through a major honours research project.</p><p>Through a comprehensive blend of theory, practical experiences and clinical placements you’ll develop the skills to expertly diagnose disease. You’ll graduate with the knowledge, skills and experience to thrive in your medical laboratory career – in whatever setting you choose.</p>',
    course_duration_per_week = 208,
    total_course_duration = '4 year(s) full-time',
    offshore_tuition_fee = 50500,
    onshore_tuition_fee = NULL,
    entry_requirements = '<table><tbody><tr><td><strong>Academic Requirements</strong></td><td><ul><li>Completion of a secondary education qualification equivalent to the South Australian Certificate of Education (SACE)</li><li>Completion of an award from a registered training organisation (RTO) at Certificate IV (AQF level 4) or higher</li><li>Successful completion of at least 6 months full-time study (or equivalent part-time) in a higher education award program in an undergraduate diploma (AQF level 5) or higher</li></ul></td></tr><tr><td><strong>English Proficiency</strong></td><td><ul><li>International students who speak English as an additional language must have obtained one of the following standards within the last two years prior to admission</li><li>Where previous study/work experience was conducted in English, the application must be accompanied by certified documentation from the educational institution/employer certifying that the language of instruction/employment was English</li><li>IELTS Overall 6.5</li><li>IELTS Reading 6.5</li><li>IELTS Listening 6.5</li><li>IELTS Speaking 6.5</li><li>IELTS Writing 6.5</li><li>Equivalent English qualifications link provided for comprehensive list of accepted tests</li></ul></td></tr><tr><td><strong>International admissions by country</strong></td><td><ul><li>Australia ATAR 80</li><li>Bangladesh Higher Secondary Certificate (HSC) 4.90</li><li>Canada Ontario Secondary School Diploma (OSSD) 75%</li><li>China Gaokao 70%</li><li>Denmark Studentereksamen (stx: Upper Secondary School Diploma) 4 (Fair)</li><li>France French Baccalaureate 12.0</li><li>Global International Baccalaureate 28</li><li>Hong Kong Diploma of Secondary Education (HKDSE) 18</li><li>India CBSE and CISCE 75</li><li>India State Board Examinations 90</li><li>Indonesia SMA III 80%</li><li>Kenya Certificate of Secondary Education (KCSE) B+</li><li>Malaysia Matrikulasi 3.00</li><li>Malaysia Sijil Tinggi Persekolahan Malaysia (STPM) 3.00</li><li>Malaysia United Entrance Certificate (UEC) 19</li><li>Nepal National Examinations Board (NEB) 3.21</li><li>Norway Upper Secondary School Certificate (Vitnemal fra den Videregaende Skole) / Vitnemal For Videregaende Opplaering 4.0</li><li>Phillippines High School Diploma (Grade 12) (Academic Track) K12 88%</li><li>Singapore Singapore GCE Advanced Levels 9</li><li>South Korea College Scholastic Ability Test (CSAT) 330</li><li>Sri Lanka GCE A Levels 10</li><li>Sweden Upper Secondary School Leaving Certificate 15.0</li><li>Taiwan GSAT % 70%</li><li>Thailand Matayom 6 3.60</li><li>UK / Global GCE Advanced Levels 9</li><li>USA / Global Advanced Placement (AP) 9</li><li>USA / Global America College Test (ACT) 24</li><li>USA / Global Scholastic Assessment Test (SAT) 1170</li><li>Vietnam Bằng Tốt Nghiệp Trung Học Phổ Thông (Vietnamese Year 12) 8.3</li></ul></td></tr><tr><td><strong>Other</strong></td><td><ul><li>In cases where there are more eligible applicants than available places, admission will be competitive with ranks based on the entry criteria</li><li>Possession of qualifications, in addition to academic entry requirements, does not guarantee a place</li><li>Applications are considered on an individual basis and selection is competitive</li></ul></td></tr></tbody></table>',
