-- Course: Bachelor of Social Work (Honours) (115757K)
UPDATE courses SET
    course_description = '<p>Our Bachelor of Social Work (Honours) provides an advanced level of knowledge in the social and behavioural sciences, with a specific focus on four major areas of study: social work theory, social work practice and skills, social policy and social research.</p><p>Our comprehensive range of core and elective courses enable you to dive deep into a wide-range of theories, principles, and approaches to working with diverse populations – equipping you with the skills needed for social and human services work.</p><p>Additionally, you’ll undertake your own research project under the guidance of an experienced supervisor, with the opportunity to publish post-completion.</p><p>Throughout your studies, you’ll have multiple opportunities to put your learning into practice. Hone your professional skillset with simulated client studios and 2 x 500-hour industry placements.</p><p>These combined experiences guarantee that you will graduate equipped with advanced knowledge, techniques, and professional skills essential for success in your social work career.</p>',
    course_duration_per_week = 208,
    total_course_duration = '4 year(s) full-time',
    offshore_tuition_fee = 43400,
