-- Course: Master of Pharmacy (117266B)
UPDATE courses SET
    course_description = '<p>Studying pharmacy offers a dynamic and rewarding path. Join a cohort of students passionate about healthcare, science and improving people''s lives.</p><p>Combine the Intern Training Program (ITP) with a supervised internship. Engage in real workplace environments to advance your pharmacy practice skills.</p><p>Learn from award-winning teaching staff including academics and health professionals. Build valuable industry networks and relationships. Be guided by curriculum that is informed by peak industry bodies.</p><p>Build strong interpersonal and problem-solving skills to make ethical decisions. Learn how to multitask and become familiar with pharmacy software.</p><p>Package this degree with a Bachelor of Pharmacy (Honours) or our Pharmacy double degree to guide your professional career transition.</p><p>Shape the future of healthcare in innovative and transformative ways with an Adelaide University degree. You’ll explore diverse opportunities to expand the scope of pharmacist duties.</p>',
    course_duration_per_week = 52,
    total_course_duration = '1 year(s) full-time',
    offshore_tuition_fee = 52200,
    onshore_tuition_fee = NULL,
    entry_requirements = '<table><tbody><tr><td><strong>Academic Requirements</strong></td><td>A completed Bachelor of Pharmacy (Honours) from a recognised higher education institution that has provisional or full Australian Pharmacy Council (APC) accreditation in Australia or New Zealand.</td></tr><tr><td><strong>Other</strong></td><td><ul><li>To be eligible, an applicant must have achieved the minimum entry requirements and demonstrate they fulfil any prerequisite and essential criteria for admission.</li><li>In cases where there are more eligible applicants than available places, admission will be competitive with ranks based on the entry criteria.</li></ul></td></tr><tr><td><strong>Essential Requirements</strong></td><td><ul><li>Obtain or apply for provisional registration through the Australian Health Practitioner Regulation Agency (AHPRA). Enrolment into the program will be finalised when provisional AHPRA registration is achieved. Students who fail to gain provisional registration or who have their registration rescinded during the program, will be unable to continue in the program.</li><li>Arrange their supervised practice (internship) under the supervision of a preceptor approved by the Pharmacy Board of Australia.</li></ul></td></tr><tr><td><strong>English Proficiency</strong></td><td><ul><li>International students who speak English as an additional language must have obtained one of the following standards within the last two years prior to admission.</li><li>Where previous study/work experience was conducted in English, the application must be accompanied by certified documentation from the educational institution/employer certifying that the language of instruction/employment was English.</li><li>IELTS Overall 7</li><li>IELTS Reading 7</li><li>IELTS Listening 7</li><li>IELTS Speaking 7</li><li>IELTS Writing 7</li></ul></td></tr></tbody></table>',
    apply_form = 'https://adelaideuni.edu.au/study/degrees/master-of-pharmacy/',
    updated_at = NOW()
WHERE cricos_course_code = '117266B';

-- Course: Bachelor of Interior Architecture (Honours) (115721M)
UPDATE courses SET
    course_description = '<p>The Bachelor of Interior Architecture (Honours) equips you with advanced design knowledge and practical skills. You’ll focus on creating innovative and impactful interior spaces. </p><p>Explore research-driven design practices. Master spatial planning, sustainability and the integration of modern technologies with human wellbeing at the core. </p><p>You’ll work on complex projects that address real-world challenges, gaining insights into the social, environmental and technological aspects of interior architecture. </p><p>Collaborative studio work and professional placements provide hands-on experience. You’ll enhance your portfolio and be prepared for specialised roles in the industry. </p><p>Graduate with the skills to pursue careers in areas like commercial design, sustainable design, adaptive re-use and placemaking. </p>',
    course_duration_per_week = 208,
    total_course_duration = '4 year(s) full-time',
    offshore_tuition_fee = 46700,
    onshore_tuition_fee = NULL,
