-- Course: Bachelor of Teaching (Primary) (Honours) (115762B)
UPDATE courses SET
    course_description = '<p>Watching your students expand their minds and reach their potential is a true gift. It’s a rewarding and diverse career with endless opportunities to make a meaningful impact. </p><p>Become a qualified primary school teacher with Adelaide University’s Bachelor of Teaching (Primary) (Honours) and teach Reception to Year 6, children from around the ages of 5 to 11. </p><p>Discover various educational philosophies and teaching methods. Learn to create safe, inclusive and culturally responsive classrooms. Get familiar with digital tools and technologies for teaching. </p><p>From your first year, you’ll gain practical experience in real schools and classrooms, preparing you to step confidently into your teaching career. </p><p>Adelaide University is ranked #89 in the world for Education Studies (<a href="https://www.timeshighereducation.com/world-university-rankings/2026/subject-ranking/education" rel="noopener noreferrer" target="_blank">Times Higher Education, 2026</a>). You can also choose to study this program at our regional campuses in <a href="https://adelaideuni.edu.au/why-adelaide/campuses/mount-gambier-campus/" rel="noopener noreferrer" target="_blank">Mount Gambier</a> and <a href="https://adelaideuni.edu.au/why-adelaide/campuses/whyalla-campus/" rel="noopener noreferrer" target="_blank">Whyalla</a>.</p>',
    course_duration_per_week = 208,
    total_course_duration = '4 year(s) full-time',
    offshore_tuition_fee = 43400,
    onshore_tuition_fee = NULL,
    entry_requirements = '<table><tbody><tr><td><strong>Academic Requirements</strong></td><td><ul><li>Secondary education (Year 12): Completion of a secondary education qualification equivalent to the South Australian Certificate of Education (SACE).</li><li>Vocational Education and Training (VET): Completion of an award from a registered training organisation (RTO) at Diploma (AQF level 5) or higher.</li><li>Higher education study: Successful completion of at least 6 months full-time study (or equivalent part-time) in a higher education award program.</li><li>International admissions by country country-specific requirements and scores (Australia ATAR 75; Bangladesh HSC 4.85; Canada OSSD 70%; China Gaokao 65%; Denmark Studentereksamen 4; France French Baccalaureate 11.5; Global IB 26; Hong Kong HKDSE 17; India CBSE and CISCE 70; India State Board 85; Indonesia SMA III 78%; Kenya KCSE B+; Malaysia Matrikulasi 2.78; Malaysia STPM 2.78; Malaysia UEC 20; Nepal NEB 3.01; Norway Upper Secondary School Certificate 3.6; Philippines High School Diploma K12 87%; Singapore GCE A Levels 8; South Korea CSAT 320; Sri Lanka GCE A Levels 9; Sweden Upper Secondary School Leaving Certificate 14.0; Taiwan GSAT 65%; Thailand Matayom 6 3.40; UK/Global GCE A Levels 8; USA/Global AP 8; USA/Global ACT 22; USA/Global SAT 1130; Vietnam Year 12 8).</li></ul></td></tr><tr><td><strong>English Proficiency</strong></td><td><ul><li>International students who speak English as an additional language must have obtained one of the following standards within the last two years prior to admission.</li><li>IELTS: Overall 7, Reading 7, Listening 7, Speaking 7, Writing 7.</li><li>Equivalent English qualifications accepted by Adelaide University (see link).</li><li>Where previous study/work experience was conducted in English, application must be accompanied by certified documentation certifying English was language of instruction/employment.</li></ul></td></tr><tr><td><strong>Other</strong></td><td><ul><li>In cases where there are more eligible applicants than available places, admission will be competitive with ranks based on the entry criteria.</li><li>Possession of qualifications in addition to academic entry requirements does not guarantee a place; applications considered individually and selection is competitive.</li><li>All applicants required to submit a 400-600 word Teaching Capabilities Statement (TCS) describing motivation to teach; assesses non-academic entry requirements per national teacher education program standards.</li><li>Prior to professional experience placement involving contact with minors (under 18), students required to provide successful Working with Children Check (WWCC) with Department of Human Services.</li><li>WWCC clearance required for visits to education sites in other courses, to enter any school, pre-school or childcare centre for any reason including placement, observation, internships or visits.</li><li>These placements form a compulsory part of the program.</li><li>Procedure for obtaining clearance provided with letter of offer and viewable at Teaching and Education Placements web page.</li></ul></td></tr></tbody></table>',
    apply_form = 'https://adelaideuni.edu.au/study/degrees/bachelor-of-teaching-primary-honours/',
    updated_at = NOW()
WHERE cricos_course_code = '115762B';

-- Course: Master of Aboriginal Studies (115892C)
UPDATE courses SET
    course_description = '<p>Our Master of Aboriginal Studies privileges First Nations knowledges, pedagogies and voices. It is designed for postgraduate students of any discipline with an interest in Aboriginal history, cultures, politics and education. </p><p>Through a mix of theoretical and practical learning, you’ll explore Aboriginal issues and worldviews in relation to health, law, history, education, the environment, policy and research. </p><p>Learn from highly respected Aboriginal professionals, including academics and lecturers who offer a wealth of valuable insight and experience. </p><p>You’ll undertake a significant research project in an area of interest –from Indigenous agricultural practices to First Nations poetry – exploring relevant global, cultural, social and political themes. You’ll gain a deep appreciation of Aboriginal languages, research and knowledges – and how they can drive local solutions and global impact. </p><p>You’ll graduate with advanced research and project management skills, equipped to meaningfully collaborate with Aboriginal communities in Australia – and champion positive change. </p>',
    course_duration_per_week = 104,
    total_course_duration = '2 year(s) full-time',
    offshore_tuition_fee = 43400,
    onshore_tuition_fee = NULL,
    entry_requirements = '<table><tbody><tr><td><strong>Academic Requirements</strong></td><td><ul><li>A completed bachelor (AQF level 7) or bachelor honours (AQF level 8) degree or equivalent from a recognised higher education institution; OR</li><li>A completed nested or related graduate certificate (AQF level 8) or higher or equivalent from a recognised higher education institution.</li><li>In cases where there are more eligible applicants than available places, admission will be competitive with ranks based on the entry criteria.</li><li>Possession of English qualifications, in addition to the academic entry requirements, does not guarantee a place; applications are considered individually and selection is competitive.</li></ul></td></tr><tr><td><strong>English Proficiency</strong></td><td><ul><li>International students who speak English as an additional language must have obtained one of the following standards within the last two years prior to admission.</li><li>Where previous study/work experience was conducted in English, the application must be accompanied by certified documentation from the educational institution/employer certifying that the language of instruction/employment was English.</li><li>IELTS Overall 6.5</li><li>IELTS Reading 6</li><li>IELTS Listening 6</li><li>IELTS Speaking 6</li><li>IELTS Writing 6</li><li>Equivalent English qualifications link provided for comprehensive list of accepted tests and other information.</li></ul></td></tr></tbody></table>',
    apply_form = 'https://adelaideuni.edu.au/study/degrees/master-of-aboriginal-studies/',
    updated_at = NOW()
WHERE cricos_course_code = '115892C';

-- Course: Bachelor of Psychology (Honours) (Cognitive Neuroscience) (118396F)
UPDATE courses SET
    course_description = '<p>Adelaide University’s Bachelor of Psychology (Honours)(Cognitive Neuroscience) builds advanced professional and research skills.</p><p>You’ll learn all about psychological theories and concepts as they apply in industry. With a cognitive neuroscience focus, you’ll develop your understanding of human anatomy and how it shapes our brain development.</p><p>Put your skills into practice in our dedicated campus facilities. Get experience in our Cognitive Neuroscience Laboratory, Psychology Clinic, and Sleep and Chronobiology Laboratory. Here, you’ll see how different brains respond to the same stimuli. Develop your ethics and confidence working with real clients. Learn how to communicate complex concepts and engage with diverse populations.</p><p>Your honours year expands upon your studies with advanced research activities and professional development opportunities.</p><p>You’ll graduate with high-level insights into how the brain functions – and why people behave the way they do. You’ll be ready to apply your skills in the many roles working directly with people, from human resources and marketing to technology and advocacy.</p><p>Students wishing to become a registered psychologist will need to undertake further study after completion of this program. Students would need to apply for a Bachelor of Psychology (Honours) 1 year (Program code: HBPSY), and a Master of Psychology program (Master of Psychology (Clinical), (Program code: MAPSC); OR Master of Psychology (Health), (Program code: MAPSH); OR Master of Psychology (Organisational and Human Factors), (Program code: MAPSO).</p>',
    course_duration_per_week = 208,
    total_course_duration = '4 year(s) full-time',
    offshore_tuition_fee = 46700,
    onshore_tuition_fee = NULL,
    entry_requirements = '<table><tbody><tr><td><strong>Academic Requirements</strong></td><td><ul><li>Completion of a secondary education qualification equivalent to the South Australian Certificate of Education (SACE)</li><li>Completion of an award from a registered training organisation (RTO) at Advanced Diploma (AQF level 6) or higher</li><li>Successful completion of at least 6 months full-time study (or equivalent part-time) in a higher education award program at undergraduate Diploma (AQF level 5)</li><li>Australia ATAR 95</li><li>Bangladesh Higher Secondary Certificate (HSC) 4.99</li><li>Canada Ontario Secondary School Diploma (OSSD) 90%</li><li>China Gaokao 85%</li><li>Denmark Studentereksamen (stx: Upper Secondary School Diploma) 10 (Very Good)</li><li>France French Baccalaureate 14.5</li><li>Global International Baccalaureate 36</li><li>Hong Kong Diploma of Secondary Education (HKDSE) 23</li><li>India CBSE and CISCE 90</li><li>India State Board Examinations 99</li><li>Indonesia SMA III 95%</li><li>Kenya Certificate of Secondary Education (KCSE) A</li><li>Malaysia Matrikulasi 3.55</li><li>Malaysia Sijil Tinggi Persekolahan Malaysia (STPM) 3.55</li><li>Malaysia United Entrance Certificate (UEC) 8</li><li>Nepal National Examinations Board (NEB) 3.81</li><li>Norway Upper Secondary School Certificate (Vitnemal fra den Videregaende Skole) / Vitnemal For Videregaende Opplaering 5.2</li><li>Phillippines High School Diploma (Grade 12) (Academic Track) K12 97%</li><li>Singapore Singapore GCE Advanced Levels 13</li><li>South Korea College Scholastic Ability Test (CSAT) 368</li><li>Sri Lanka GCE A Levels 14</li><li>Sweden Upper Secondary School Leaving Certificate 17.5</li><li>Taiwan GSAT % 85%</li><li>Thailand Matayom 6 3.98</li><li>UK / Global GCE Advanced Levels 14</li><li>USA / Global Advanced Placement (AP) 13</li><li>USA / Global America College Test (ACT) 32</li><li>USA / Global Scholastic Assessment Test (SAT) 1360</li><li>Vietnam Bằng Tốt Nghiệp Trung Học Phổ Thông (Vietnamese Year 12) 9</li></ul></td></tr><tr><td><strong>English Proficiency</strong></td><td><ul><li>International students who speak English as an additional language must have obtained one of the following standards within the last two years prior to admission</li><li>IELTS Overall 6.5</li><li>IELTS Reading 6</li><li>IELTS Listening 6</li><li>IELTS Speaking 6</li><li>IELTS Writing 6</li><li>Equivalent English qualifications link available for comprehensive list of English language tests accepted</li><li>Where previous study/work experience was conducted in English, the application must be accompanied by certified documentation from the educational institution/employer certifying that the language of instruction/employment was English</li></ul></td></tr><tr><td><strong>Other</strong></td><td><ul><li>In cases where there are more eligible applicants than available places, admission will be competitive with ranks based on the entry criteria</li><li>Possession of one or more of these qualifications, in addition to the academic entry requirements, does not, in itself, guarantee a place at Adelaide University</li><li>Applications are considered on an individual basis and selection is competitive</li></ul></td></tr></tbody></table>',
