-- Course: Bachelor of Business (115681C)
UPDATE courses SET
    course_description = '<p>This degree will build your foundational knowledge in key business disciplines while expanding your proficiency in digital technologies. Learn about core aspects of business including accounting, marketing, management and company law. Then explore topics specific to your major in Digital Business, such as disruptive technologies, future digital trends and managing digital transformation projects.</p><p>Customise your studies by choosing from a range of electives that will expand your knowledge in diverse areas of business. You’ll also have the opportunity to apply for an Accenture WIL placement in your final year, which will allow you to explore your career options. Graduate ready to manage and consult with companies utilising the latest digital technologies to drive business growth.</p>',
    course_duration_per_week = 156,
    total_course_duration = '3 year(s) full-time',
    offshore_tuition_fee = 50500,
    onshore_tuition_fee = NULL,
    entry_requirements = '<table><tbody><tr><td><strong>Academic Requirements</strong></td><td><ul><li>Completion of a secondary education qualification equivalent to the South Australian Certificate of Education (SACE)</li><li>Completion of an award from a registered training organisation (RTO) at Certificate IV (AQF level 4) or higher</li><li>Successful completion of at least 6 months full-time study (or equivalent part-time) in a higher education award program</li></ul></td></tr><tr><td><strong>English Proficiency</strong></td><td><ul><li>International students who speak English as an additional language must have obtained one of the following standards within the last two years prior to admission</li><li>Where previous study/work experience was conducted in English, the application must be accompanied by certified documentation from the educational institution/employer certifying that the language of instruction/employment was English</li><li>IELTS Overall 6.5</li><li>IELTS Reading 6</li><li>IELTS Listening 6</li><li>IELTS Speaking 6</li><li>IELTS Writing 6</li><li>Please access the following link for a comprehensive list of English language tests accepted by Adelaide University and other important information in relation to meeting the University’s language requirements: Equivalent English qualifications</li></ul></td></tr><tr><td><strong>International admissions by country</strong></td><td><ul><li>Australia ATAR 70</li><li>Bangladesh Higher Secondary Certificate (HSC) 4.80</li><li>Canada Ontario Secondary School Diploma (OSSD) 65%</li><li>China Gaokao 60%</li><li>Denmark Studentereksamen (stx: Upper Secondary School Diploma) 4 (Fair)</li><li>France French Baccalaureate 11.0</li><li>Global International Baccalaureate 25</li><li>Hong Kong Diploma of Secondary Education (HKDSE) 16</li><li>India CBSE and CISCE 65</li><li>India State Board Examinations 80</li><li>Indonesia SMA III 75%</li><li>Kenya Certificate of Secondary Education (KCSE) B+</li><li>Malaysia Matrikulasi 2.67</li><li>Malaysia Sijil Tinggi Persekolahan Malaysia (STPM) 2.67</li><li>Malaysia United Entrance Certificate (UEC) 23</li><li>Nepal National Examinations Board (NEB) 2.81</li><li>Norway Upper Secondary School Certificate (Vitnemal fra den Videregaende Skole) / Vitnemal For Videregaende Opplaering 3.2</li><li>Philippines High School Diploma (Grade 12) (Academic Track) K12 86%</li><li>Singapore Singapore GCE Advanced Levels 7</li><li>South Korea College Scholastic Ability Test (CSAT) 300</li><li>Sri Lanka GCE A Levels 8</li><li>Sweden Upper Secondary School Leaving Certificate 13.0</li><li>Taiwan GSAT % 60%</li><li>Thailand Matayom 6 3.20</li><li>UK / Global GCE Advanced Levels 7</li><li>USA / Global Advanced Placement (AP) 7</li><li>USA / Global America College Test (ACT) 21</li><li>USA / Global Scholastic Assessment Test (SAT) 1100</li><li>Vietnam Bằng Tốt Nghiệp Trung Học Phổ Thông (Vietnamese Year 12) 7.8</li></ul></td></tr><tr><td><strong>Other</strong></td><td><ul><li>To be eligible, an applicant must have achieved at least one of the following minimum entry requirements and demonstrate they fulfil any prerequisite and essential criteria for admission</li><li>In cases where there are more eligible applicants than available places, admission will be competitive with ranks based on the entry criteria</li><li>Possession of one or more of these qualifications, in addition to the academic entry requirements, does not, in itself, guarantee a place at Adelaide University</li><li>Applications are considered on an individual basis and selection is competitive</li></ul></td></tr></tbody></table>',
    apply_form = 'https://adelaideuni.edu.au/study/degrees/bachelor-of-business-digital-business/',
    updated_at = NOW()
WHERE cricos_course_code = '115681C';

-- Course: Graduate Diploma in Aviation (115839H)
UPDATE courses SET
    course_description = '<p>Our Graduate Diploma in Aviation is a technical flight training program delivered with <a href="http://www.flyfta.com/" rel="noopener noreferrer" target="_blank">Flight Training Adelaide</a> at Parafield Airport. Applications for this program are invitation only, for students with a current enrolment in the <a href="https://adelaideuni.edu.au/study/degrees/bachelor-of-aviation-pilot" rel="noopener noreferrer" target="_blank">Bachelor of Aviation majoring in Pilot</a>. </p><p>Obtain the skills, knowledge and competencies to test for a Commercial Pilot Licence (CPL) and Multi-engine Command Instrument Rating (MECIR). These are professional qualifications recognised by the Civil Aviation Safety Authority and the International Civil Aviation Organisation. </p><p>Take introductory courses in advanced flying, aircraft navigation, night flying and instrument flying. You’ll complete ground simulator lessons and be mentored by experienced flight instructors. </p><p>While this program is an intensive study commitment, you’ll finish your studies on a rewarding career path. Graduate prepared to work as a first officer in multi-crew aircraft or as a pilot-in-command in single engine aircraft. </p>',
    course_duration_per_week = 52,
    total_course_duration = '1 year(s) full-time',
    offshore_tuition_fee = 124700,
    onshore_tuition_fee = NULL,
    entry_requirements = '<table><tbody><tr><td><strong>Other</strong></td><td><ul><li>Applications for this program are by invitation only.</li><li>Applicants are required to have a current enrolment in a qualifying Adelaide University Bachelor of Aviation degree.</li><li>Applicants will be selected via a process which includes: formal interview; AND flight aptitude test; AND assessment of Aviation English Proficiency; AND successful completion of AERO1006 Flight Training Theory 1 with a minimum of 80% class attendance; AND academic achievement, normally achieving at least a pass average within Bachelor of Aviation studies.</li><li>Students must obtain a Class I Medical Certificate before commencing flight training. Class II will be considered if Class I held in the last 3 years.</li><li>The CASA medical must not have any restrictions that would impede the student’s ability to complete the program, and must be held for the duration of the program.</li><li>Students must hold an Aviation Security Identification Card (ASIC) before enrolling in Advanced Flying.</li></ul></td></tr><tr><td><strong>Academic Requirements</strong></td><td><ul><li>Current enrolment in a qualifying Adelaide University Bachelor of Aviation degree.</li><li>Successful completion of AERO1006 Flight Training Theory 1 with a minimum of 80% class attendance.</li><li>Academic achievement, normally achieving at least a pass average within Bachelor of Aviation studies.</li></ul></td></tr><tr><td><strong>Interview</strong></td><td>Formal interview (part of selection process).</td></tr><tr><td><strong>English Proficiency</strong></td><td><ul><li>International students who speak English as an additional language must have obtained one of the following standards within the last two years prior to admission: IELTS Overall 6.5, IELTS Reading 6, IELTS Listening 6, IELTS Speaking 6, IELTS Writing 6.</li><li>Where previous study/work experience was conducted in English, the application must be accompanied by certified documentation from the educational institution/employer certifying that the language of instruction/employment was English.</li><li>Assessment of Aviation English Proficiency (part of selection process).</li></ul></td></tr><tr><td><strong>Student Equipment</strong></td><td><ul><li>Class I Medical Certificate (or Class II if Class I held in last 3 years) before commencing flight training, held for duration of program.</li><li>Aviation Security Identification Card (ASIC) before enrolling in Advanced Flying.</li></ul></td></tr></tbody></table>',
    apply_form = 'https://adelaideuni.edu.au/study/degrees/graduate-diploma-in-aviation/',
    updated_at = NOW()
WHERE cricos_course_code = '115839H';

